pivotal role&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW223456913 BCX8&quot;&gt; to help execute an ambitious vision&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW223456913 BCX8&quot;&gt;.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW223456913 BCX8&quot; data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Key Responsibilities:&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Co-own the product&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
